CREATE TABLE "api_keys" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "name" TEXT NOT NULL CHECK (length("name") <= 128),
    "key_hash" TEXT NOT NULL CHECK (length("key_hash") <= 64),
    "prefix" TEXT NOT NULL CHECK (length("prefix") <= 12),
    "scopes" TEXT NOT NULL DEFAULT '[]' CHECK ("scopes" IS NULL OR json_valid("scopes")),
    "created_by" INTEGER NOT NULL,
    "last_used_at" INTEGER,
    "expires_at" INTEGER,
    "revoked" INTEGER NOT NULL DEFAULT 0 CHECK ("revoked" IN (0, 1)),
    "created_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000000 AS INTEGER)),
    UNIQUE (key_hash)
) STRICT;


