CREATE INDEX "idx_stats_msg_user_date" ON "stats_messages" (from_user, date);
CREATE INDEX "idx_stats_msg_type" ON "stats_messages" (msg_type);
CREATE INDEX "idx_stats_msg_thread" ON "stats_messages" (chat_id, message_thread_id) WHERE (message_thread_id IS NOT NULL);

CREATE TABLE "stats_reactions" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "user_id" INTEGER NOT NULL,
    "chat_id" INTEGER NOT NULL,
    "message_id" INTEGER NOT NULL,
    "reaction_key" TEXT NOT NULL CHECK (length("reaction_key") <= 64),
    "reaction_type" TEXT NOT NULL CHECK (length("reaction_type") <= 16),
    "date" INTEGER NOT NULL,
    UNIQUE (user_id, chat_id, message_id, reaction_key)
) STRICT;

CREATE INDEX "idx_stats_reactions_chat_date" ON "stats_reactions" (chat_id, date);

CREATE TABLE "stats_user_events" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "message_id" INTEGER NOT NULL,
    "chat_id" INTEGER NOT NULL,
    "user_id" INTEGER NOT NULL,
    "date" INTEGER NOT NULL,
    "event" TEXT NOT NULL CHECK (length("event") <= 32)
) STRICT;

CREATE INDEX "idx_stats_ue_chat_date" ON "stats_user_events" (chat_id, date);

CREATE TABLE "stats_user_names" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "user_id" INTEGER NOT NULL,
    "date" INTEGER NOT NULL,
    "username" TEXT CHECK (length("username") <= 64),
    "display_name" TEXT CHECK (length("display_name") <= 256),
    UNIQUE (user_id, date)
) STRICT;


CREATE TABLE "thread_policies" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "group_id" INTEGER NOT NULL,
    "thread_id" INTEGER,
    "name" TEXT CHECK (length("name") <= 256),
    "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)),
    FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE,
    UNIQUE (group_id, thread_id)
) STRICT;


CREATE TABLE "user_group_policies" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "user_id" INTEGER NOT NULL,
    "group_id" INTEGER NOT NULL,
    "role_override" TEXT CHECK ("role_override" IN ('owner', 'admin', 'moderator', 'user', 'restricted', 'banned')),
    "allow_pm_override" INTEGER CHECK ("allow_pm_override" IN (0, 1)),
    FOREIGN KEY (group_id) REFERENCES groups(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE (user_id, group_id)
) STRICT;


CREATE TABLE "user_permissions" (
    "id" INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL CHECK ("id" BETWEEN -2147483648 AND 2147483647),
    "user_id" INTEGER NOT NULL,
    "plugin" TEXT NOT NULL CHECK (length("plugin") <= 32),
    "feature" TEXT NOT NULL CHECK (length("feature") <= 64),
    "granted_by" INTEGER NOT NULL,
    "granted_at" INTEGER NOT NULL DEFAULT (CAST(unixepoch('subsec') * 1000000 AS INTEGER)),
    "expires_at" INTEGER,
    "grant_source" TEXT NOT NULL DEFAULT 'manual' CHECK (length("grant_source") <= 16),
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE (user_id, plugin, feature)
) STRICT;


CREATE TABLE "users" (
    "id" INT NOT NULL,
    "username" TEXT CHECK (length("username") <= 64),
    "first_name" TEXT CHECK (length("first_name") <= 128),
    "role" TEXT NOT NULL DEFAULT 'user' CHECK ("role" IN ('owner', 'admin', 'moderator', 'user', 'restricted', 'banned')),
    "language" TEXT NOT NULL DEFAULT 'en' CHECK (length("language") <= 8),
    "theme" TEXT NOT NULL DEFAULT 'macchiato' CHECK (length("theme") <= 32),
    "ban_until" INTEGER,
    "created_at" INTEGER NOT NULL,
    "updated_at" INTEGER NOT NULL,
    "is_premium" INTEGER NOT NULL DEFAULT 0 CHECK ("is_premium" IN (0, 1)),
    "photo_url" TEXT CHECK (length("photo_url") <= 512),
    PRIMARY KEY (id)
) STRICT;


CREATE INDEX "cookies_user_fk" ON "cookies" ("user_id");
CREATE INDEX "inbox_categories_parent_fk" ON "inbox_categories" ("parent_id");
CREATE INDEX "inbox_gh_folders_parent_fk" ON "inbox_gh_folders" ("parent_id");
CREATE INDEX "inbox_item_categories_actor_fk" ON "inbox_item_categories" ("attached_by_user_id");
CREATE INDEX "inbox_item_to_star_star_fk" ON "inbox_item_to_star" ("gh_star_id");
CREATE INDEX "inbox_item_to_star_folder_fk" ON "inbox_item_to_star" ("folder_id");
CREATE INDEX "user_group_policies_group_user" ON "user_group_policies" ("group_id", "user_id");
CREATE UNIQUE INDEX thread_policies_default_unique ON thread_policies(group_id) WHERE thread_id IS NULL;

CREATE VIEW stats_user_latest_name AS
SELECT current.user_id, current.username, current.display_name, current.date
FROM stats_user_names AS current
WHERE NOT EXISTS (SELECT 1 FROM stats_user_names AS newer
                  WHERE newer.user_id = current.user_id AND newer.date > current.date);
